import { useState, useEffect } from 'react';

const BookList = ({ onBookUpdated, onBookDeleted }) => {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchBooks = async () => {
    try {
      setLoading(true);
      const response = await fetch('http://localhost:8000/books');
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setBooks(data);
      setError(null);
    } catch (err) {
      setError(`Failed to fetch books: ${err.message}`);
      console.error('Error fetching books:', err);
    } finally {
      setLoading(false);
    }
  };

  const updateBookStatus = async (id, newStatus) => {
    try {
      const response = await fetch(`http://localhost:8000/books/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status: newStatus }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const updatedBook = await response.json();
      onBookUpdated(updatedBook);
      fetchBooks(); // Refresh the list
    } catch (err) {
      setError(`Failed to update book status: ${err.message}`);
      console.error('Error updating book:', err);
    }
  };

  const deleteBook = async (id) => {
    try {
      const response = await fetch(`http://localhost:8000/books/${id}`, {
        method: 'DELETE',
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      onBookDeleted(id);
      fetchBooks(); // Refresh the list
    } catch (err) {
      setError(`Failed to delete book: ${err.message}`);
      console.error('Error deleting book:', err);
    }
  };

  useEffect(() => {
    fetchBooks();
  }, []);

  if (loading) {
    return <div className="loading">Loading books...</div>;
  }

  if (error) {
    return (
      <div className="error">
        <p>Error: {error}</p>
      </div>
    );
  }

  return (
    <div className="book-list">
      <h2>My Books</h2>
      {books.length === 0 ? (
        <p>No books in the list yet.</p>
      ) : (
        <ul className="books">
          {books.map((book) => (
            <li key={book.id} className="book-item">
              <div className="book-info">
                <h3>{book.title}</h3>
                <p>by {book.author}</p>
                <div className="book-status">
                  <span className="status-label">Status:</span>
                  <select
                    value={book.status}
                    onChange={(e) => updateBookStatus(book.id, e.target.value)}
                    className="status-select"
                  >
                    <option value="to-read">To Read</option>
                    <option value="reading">Reading</option>
                    <option value="done">Done</option>
                  </select>
                </div>
              </div>
              <button
                onClick={() => deleteBook(book.id)}
                className="delete-button"
                aria-label={`Delete ${book.title}`}
              >
                Delete
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default BookList;

import { useState } from 'react';

const BookForm = ({ onBookAdded }) => {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState('to-read');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!title.trim() || !author.trim()) {
      setError('Title and author are required');
      return;
    }

    try {
      setLoading(true);
      setError(null);

      const response = await fetch('http://localhost:8000/books', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          title: title.trim(),
          author: author.trim(),
          status: status,
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const newBook = await response.json();
      onBookAdded(newBook);

      // Reset form
      setTitle('');
      setAuthor('');
      setStatus('to-read');
    } catch (err) {
      setError(`Failed to add book: ${err.message}`);
      console.error('Error adding book:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="book-form">
      <h2>Add New Book</h2>
      <form onSubmit={handleSubmit}>
        <div className="form-group">
          <label htmlFor="title">Title:</label>
          <input
            type="text"
            id="title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            required
            className="form-input"
          />
        </div>

        <div className="form-group">
          <label htmlFor="author">Author:</label>
          <input
            type="text"
            id="author"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            required
            className="form-input"
          />
        </div>

        <div className="form-group">
          <label htmlFor="status">Status:</label>
          <select
            id="status"
            value={status}
            onChange={(e) => setStatus(e.target.value)}
            className="form-select"
          >
            <option value="to-read">To Read</option>
            <option value="reading">Reading</option>
            <option value="done">Done</option>
          </select>
        </div>

        {error && <div className="error-message">{error}</div>}

        <button 
          type="submit" 
          disabled={loading}
          className="submit-button"
        >
          {loading ? 'Adding...' : 'Add Book'}
        </button>
      </form>
    </div>
  );
};

export default BookForm;

import { useState } from 'react';
import BookList from './components/BookList';
import BookForm from './components/BookForm';
import './App.css';

function App() {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleBookAdded = (newBook) => {
    // The BookList component will automatically refresh, but we can show a success message if needed
    console.log('Book added:', newBook);
  };

  const handleBookUpdated = (updatedBook) => {
    // The BookList component will automatically refresh
    console.log('Book updated:', updatedBook);
  };

  const handleBookDeleted = (deletedBookId) => {
    // The BookList component will automatically refresh
    console.log('Book deleted:', deletedBookId);
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>BookTrack</h1>
        <p>Track the books you read</p>
      </header>

      <main className="app-main">
        <div className="app-content">
          <BookForm onBookAdded={handleBookAdded} />

          <div className="divider"></div>

          <BookList 
            onBookUpdated={handleBookUpdated} 
            onBookDeleted={handleBookDeleted} 
          />
        </div>
      </main>
    </div>
  );
}

export default App;

